#!/data/data/com.termux/files/usr/bin/bash\n# One-file Jarvis Orb installer for Termux.\nset -euo pipefail\nROOT="$HOME/jarvis"\nTMP="$(mktemp -d)"\ncleanup(){ rm -rf "$TMP"; }\ntrap cleanup EXIT\nawk '/^__JARVIS_ORB_PAYLOAD__$/{go=1;next}go{print}' "$0" | base64 -d | tar -xzf - -C "$TMP"\npkg update -y\npkg install -y python termux-api\npython -m pip install --upgrade requests >/dev/null\nmkdir -p "$ROOT/orb" "$ROOT/memory" "$ROOT/history"\ncp "$TMP/jarvis-orb/orb.html" "$ROOT/orb/orb.html"\ncp "$TMP/jarvis-orb/orb_server.py" "$ROOT/orb/orb_server.py"\ncp "$TMP/jarvis-orb/jarvis.py" "$ROOT/jarvis.py"\ncp "$TMP/jarvis-orb/README.md" "$ROOT/README-ORB.md"\nchmod +x "$ROOT/orb/orb_server.py" "$ROOT/jarvis.py"\ncat > "$PREFIX/bin/jarvis-orb" <<'SH'\n#!/data/data/com.termux/files/usr/bin/bash\nROOT="$HOME/jarvis"\nif ! pgrep -f 'orb_server.py' >/dev/null 2>&1; then\n  nohup python "$ROOT/orb/orb_server.py" >/dev/null 2>&1 &\n  sleep 1\nfi\ntermux-open-url http://127.0.0.1:8765\nSH\ncat > "$PREFIX/bin/jarvis" <<'SH'\n#!/data/data/com.termux/files/usr/bin/bash\njarvis-orb\nexec python "$HOME/jarvis/jarvis.py" "$@"\nSH\ncat > "$PREFIX/bin/jarvis-voice" <<'SH'\n#!/data/data/com.termux/files/usr/bin/bash\njarvis-orb\nexec python "$HOME/jarvis/jarvis.py" --voice\nSH\nchmod +x "$PREFIX/bin/jarvis" "$PREFIX/bin/jarvis-orb" "$PREFIX/bin/jarvis-voice"\nprintf '\nInstalled. Start Jarvis with:\n  jarvis-voice\n\nFor voice input/output, install the Termux:API Android companion app and allow microphone access.\n'\nexit 0\n__JARVIS_ORB_PAYLOAD__\nH4sIAAAAAAAAA+xa+3PbtrLuz/or0KQpSYmiHpZshzLTycNtcpvX2G5zM65HByJBiTVfhyBt6yj6\n3++3ACnJtZOcznTOmTtTZmKSwGKxWOzjW1C/8+Iqkt2smPXw31mUSfzNX331ce2PRnQfHIwHu3e6\nxvv9vW8G4+HBaH80Ptg7+KY/GI0H+9+w/l8uyT1XJUteMPZNwJdllvLP0n2t///pdfRtkPnlMheM\ntv5J60jdjhaCB0+OElFylvJEeA+uInGdZ0X5gPlZWoq09B5cR0G58AJxFfmiq17sKI3KiMdd6fNY\neAM74TdRUiWb90qKQr3wGd7T7MGTozIqY/Hkf5QZHvX0W+tIlku6t1ez7KYro39F6dydZUWA4WhZ\nk5D2LAuWq4QX8yh1+xMlgDvo9x9NFiKaL0r9nF2JIoyza3cRBYFIJzPu